<script lang="ts">
  import { miltankFarm } from '../stores/miltankFarm.svelte.ts';
  import { game } from '../../gameManager.ts';
  import MiltankGuardianPicker from './MiltankGuardianPicker.svelte';
  import { buildFeedButtonTooltipContent } from '../lib/miltankFarmFeedTooltip.ts';
  import { miltankFarmTooltipHandlers } from '../ui/scheduleTooltipHelpers.ts';
  import { computeMilkCyclePct } from '../lib/miltankFarmDisplay.ts';
  import { MILK_ICON_URL } from '../lib/miltankFarmClaimFeedback.ts';
  import {
    guardianOverworldStyleString,
    hasGuardianOverworldSprites,
  } from '../lib/guardianOverworldSprites.ts';

  let snap = $derived(miltankFarm.snapshot);
  let ui = $derived(snap.ui);

  let engagePastureName = $derived(
    snap.pastureSprites.find(
      (s) => s.uid === snap.activeThreatSprites.find((t) => t.id === snap.pendingThreatEngageId)?.pastureUid,
    )?.name ?? snap.selectedPastureName,
  );

  let currentIdx = $derived(
    snap.pastureSprites.findIndex((s) => s.uid === snap.selectedPastureUid),
  );
  let hasMultipleMiltanks = $derived(snap.pastureSprites.length > 1);
  let prevUid = $derived(
    hasMultipleMiltanks && currentIdx >= 0
      ? snap.pastureSprites[(currentIdx - 1 + snap.pastureSprites.length) % snap.pastureSprites.length].uid
      : null,
  );
  let nextUid = $derived(
    hasMultipleMiltanks && currentIdx >= 0
      ? snap.pastureSprites[(currentIdx + 1) % snap.pastureSprites.length].uid
      : null,
  );
  let positionLabel = $derived(
    currentIdx >= 0 ? `${currentIdx + 1} / ${snap.pastureSprites.length}` : '',
  );
  let selectedSprite = $derived(
    snap.pastureSprites.find((s) => s.uid === snap.selectedPastureUid) ?? snap.selectedPastureSprite,
  );

  let miltankSpriteUrl = $derived(
    selectedSprite?.shiny
      ? 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/shiny/241.png'
      : 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/241.png',
  );

  let milkCyclePct = $derived(computeMilkCyclePct(snap.pendingFraction));
  let stockFull = $derived(snap.storedMilk >= snap.stockCap && snap.stockCap > 0);
  let satietyPct = $derived(
    snap.satietyMax > 0
      ? Math.min(100, Math.ceil((snap.satiety / snap.satietyMax) * 100 - 1e-9))
      : 0,
  );
  let xpPct = $derived(
    snap.xpNeededInLevel != null && snap.xpNeededInLevel > 0
      ? Math.min(100, Math.round((snap.xpInLevel / snap.xpNeededInLevel) * 100))
      : 100,
  );
</script>

<div
  class="stats-content miltank-farm-modal-content miltank-farm-modal-shell"
  data-action="stopPropagation"
  data-action-stop
>
  <!-- En-tête riche avec sprite, nom, niveau, navigation multi-vaches et fermeture -->
  <div class="stats-header miltank-farm-modal-head">
    <div class="miltank-farm-modal-title-group">
      <img
        class="miltank-farm-head-sprite"
        src={miltankSpriteUrl}
        alt="Miltank"
        width="40"
        height="40"
      />
      <div class="miltank-farm-head-info">
        <h2 id="miltankFarmTitleLabel" class="miltank-farm-head-title">
          {snap.selectedPastureName || ui.title}
          {#if selectedSprite?.shiny}
            <span class="miltank-farm-shiny-star" title="Chromatique">✦</span>
          {/if}
        </h2>
        <span class="miltank-farm-head-badge">{ui.levelLabel} {snap.level}</span>
      </div>
    </div>

    {#if hasMultipleMiltanks}
      <div class="miltank-farm-modal-switcher" role="group" aria-label="Navigation Miltank">
        <button
          type="button"
          class="miltank-farm-switcher-btn"
          data-action="selectPastureMiltank"
          data-arg={prevUid}
          aria-label="Miltank précédent"
          title="Miltank précédent"
        >◀</button>
        <span class="miltank-farm-switcher-pos">{positionLabel}</span>
        <button
          type="button"
          class="miltank-farm-switcher-btn"
          data-action="selectPastureMiltank"
          data-arg={nextUid}
          aria-label="Miltank suivant"
          title="Miltank suivant"
        >▶</button>
      </div>
    {/if}

    <button type="button" class="stats-close" data-action="closeMiltankFarmModal" aria-label="Fermer">&#10005;</button>
  </div>

  {#if !snap.unlocked}
    <p class="miltank-farm-locked">{ui.locked}</p>
  {:else}
    <div class="miltank-farm-body">
      <!-- Alertes prioritaires / d'action immédiate -->
      {#if snap.incidentAlert}
        <div
          class="miltank-farm-incident-alert miltank-farm-incident-alert--{snap.incidentAlert.type}"
          role="alert"
        >
          <h3 class="miltank-farm-incident-alert-title">{snap.incidentAlert.title}</h3>
          <p class="miltank-farm-incident-alert-body">{snap.incidentAlert.body}</p>
          <button
            type="button"
            class="miltank-farm-btn miltank-farm-incident-alert-btn"
            data-action="dismissMiltankFarmIncidentAlert"
          >
            {snap.incidentAlert.dismissLabel}
          </button>
        </div>
      {/if}

      {#if stockFull && snap.storedMilk > 0}
        <div class="miltank-farm-action-alert" role="alert">
          <div class="miltank-farm-action-alert-text">
            <strong>⚠ {ui.stockLabel} pleine ({snap.storedMilk}/{snap.stockCap})</strong>
            <span>La production est interrompue jusqu'à la récolte.</span>
          </div>
          <button
            type="button"
            class="miltank-farm-btn miltank-farm-btn--primary miltank-farm-btn--claim miltank-farm-btn--alert-cta"
            data-action="claimPastureMilk"
            data-arg={snap.selectedPastureUid}
            disabled={!snap.canClaimSelected}
          >
            <img src={MILK_ICON_URL} alt="" class="miltank-farm-btn-icon" width="14" height="14" />
            {ui.claimBtn} ({snap.storedMilk})
          </button>
        </div>
      {/if}

      <!-- Synthèse d'état en 4 cellules compactes & aérées -->
      <div class="miltank-farm-status-grid">
        <!-- 1. XP -->
        <div
          class="miltank-farm-status-card miltank-farm-tooltip-host"
          data-tooltip-variant="miltank-farm"
          {...miltankFarmTooltipHandlers(() => ({ title: ui.xpLabel, body: ui.xpTooltip }))}
        >
          <div class="miltank-farm-status-head">
            <span class="miltank-farm-status-label">{ui.xpLabel}</span>
            <strong class="miltank-farm-status-value">
              {#if snap.xpNeededInLevel != null}
                {snap.xpInLevel}/{snap.xpNeededInLevel}
              {:else}
                MAX
              {/if}
            </strong>
          </div>
          <div class="miltank-farm-bar" role="progressbar" aria-valuenow={xpPct} aria-valuemin="0" aria-valuemax="100">
            <div class="miltank-farm-bar-fill" style="width: {xpPct}%"></div>
          </div>
          {#if snap.talentPointsAvailable > 0}
            <span class="miltank-farm-status-hint miltank-farm-status-hint--points">
              +{snap.talentPointsAvailable} pt{snap.talentPointsAvailable > 1 ? 's' : ''} {ui.talentPointsLabel}
            </span>
          {/if}
        </div>

        <!-- 2. Satiété (Estomac) -->
        <div
          class="miltank-farm-status-card miltank-farm-tooltip-host"
          data-tooltip-variant="miltank-farm"
          {...miltankFarmTooltipHandlers(() => ({ title: ui.satietyLabel, body: ui.satietyTooltip }))}
        >
          <div class="miltank-farm-status-head">
            <span class="miltank-farm-status-label">{ui.satietyLabel}</span>
            <strong class="miltank-farm-status-value">{snap.satiety}/{snap.satietyMax}</strong>
          </div>
          <div class="miltank-farm-bar" role="progressbar" aria-valuenow={satietyPct} aria-valuemin="0" aria-valuemax="100">
            <div class="miltank-farm-bar-fill miltank-farm-bar-fill--satiety" style="width: {satietyPct}%"></div>
          </div>
          {#if snap.satietyRoomLabel}
            <span class="miltank-farm-status-hint">{snap.satietyRoomLabel}</span>
          {:else if snap.careSatietyBadge}
            <span class="miltank-farm-status-hint miltank-farm-status-hint--care">{snap.careSatietyBadge}</span>
          {/if}
        </div>

        <!-- 3. Réserve & Prochain lait (Fusionnés) -->
        <div
          class="miltank-farm-status-card miltank-farm-tooltip-host"
          data-tooltip-variant="miltank-farm"
          {...miltankFarmTooltipHandlers(() => ({ title: ui.stockLabel, body: ui.stockTooltip }))}
        >
          <div class="miltank-farm-status-head">
            <span class="miltank-farm-status-label">{ui.stockLabel}</span>
            <strong class="miltank-farm-status-value">{snap.storedMilk}/{snap.stockCap}</strong>
          </div>
          <div class="miltank-farm-bar miltank-farm-bar--stock" role="progressbar" aria-valuenow={snap.stockFillPct} aria-valuemin="0" aria-valuemax="100">
            <div
              class="miltank-farm-bar-fill miltank-farm-bar-fill--stock"
              class:miltank-farm-bar-fill--full={stockFull}
              style="width: {snap.stockFillPct}%"
            ></div>
          </div>
          {#if stockFull}
            <span class="miltank-farm-status-hint miltank-farm-status-hint--warn">Pleine</span>
          {:else}
            <span class="miltank-farm-status-hint">{snap.narrativeNextMilkLabel ?? `${milkCyclePct}%`}</span>
          {/if}
        </div>

        <!-- 4. Production -->
        <div
          class="miltank-farm-status-card miltank-farm-tooltip-host"
          data-tooltip-variant="miltank-farm"
          {...miltankFarmTooltipHandlers(() => ({ title: ui.productionLabel, body: ui.productionTooltip }))}
        >
          <div class="miltank-farm-status-head">
            <span class="miltank-farm-status-label">{ui.productionLabel}</span>
            <div class="miltank-farm-rate-col">
              <strong class="miltank-farm-status-value" class:rate-debuffed={selectedSprite?.debuffActive}>
                {snap.milkPerHour.toFixed(3)}{ui.perHour}
              </strong>
              {#if selectedSprite?.debuffActive && snap.baseMilkPerHour != null && snap.baseMilkPerHour > snap.milkPerHour}
                <span class="miltank-farm-rate-base">
                  base : {snap.baseMilkPerHour.toFixed(3)}{ui.perHour}
                </span>
              {/if}
            </div>
          </div>
          {#if selectedSprite?.debuffActive}
            <span class="miltank-farm-status-hint miltank-farm-status-hint--debuff">
              ⚠ Blessée (−{snap.debuffLossPct ?? 50} %)
            </span>
          {:else if snap.boostRemainingLabel}
            <span class="miltank-farm-boost">{snap.boostRemainingLabel}</span>
          {:else if snap.boostActive}
            <span class="miltank-farm-boost">{ui.boostActive}</span>
          {:else}
            <span class="miltank-farm-status-hint">Taux standard</span>
          {/if}
        </div>
      </div>

      {#if snap.secondPastureCareHint}
        <p class="miltank-farm-care-hint">{snap.secondPastureCareHint}</p>
      {/if}

      <!-- Demande & Nourrissage (Regroupement ergonomique et anti-missclick) -->
      <div class="miltank-farm-request miltank-farm-section">
        <div class="miltank-farm-section-header">
          <h3 class="miltank-farm-section-title">{ui.requestLabel}</h3>
          {#if snap.requestExpiresLabel}
            <span class="miltank-farm-timer-hint">{snap.requestExpiresLabel}</span>
          {/if}
        </div>

        {#if snap.requestItemKey}
          <div class="miltank-farm-request-layout">
            <div class="miltank-farm-request-item-card">
              {#if snap.requestItemIconUrl}
                <img
                  src={snap.requestItemIconUrl}
                  alt=""
                  class="miltank-farm-request-item-icon item-sprite-img"
                  width="38"
                  height="38"
                  loading="lazy"
                  decoding="async"
                />
              {/if}
              <div class="miltank-farm-request-details">
                <strong class="miltank-farm-request-name">{snap.requestQty}× {snap.requestItemName}</strong>
                <span
                  class="miltank-farm-request-stock"
                  class:stock-ok={snap.requestOwned >= snap.requestQty}
                  class:stock-low={snap.requestOwned < snap.requestQty}
                >
                  {game?.language === 'en' ? 'Required' : 'Requis'} {snap.requestQty} · {game?.language === 'en' ? 'in bag' : 'en sac'} {snap.requestOwned}
                </span>
              </div>
            </div>

            <div class="miltank-farm-request-actions-row">
              <button
                type="button"
                class="miltank-farm-btn miltank-farm-btn--feed miltank-farm-btn--request-feed"
                class:miltank-farm-btn--primary={!stockFull && snap.canFeed}
                class:miltank-farm-btn--secondary={stockFull || !snap.canFeed}
                data-action="feedMiltankFarm"
                disabled={!snap.canFeed}
                data-tooltip-variant="miltank-farm"
                {...miltankFarmTooltipHandlers(() => buildFeedButtonTooltipContent(snap))}
              >
                {ui.feedBtn}
              </button>

              <button
                type="button"
                class="miltank-farm-btn miltank-farm-btn--reroll miltank-farm-btn--request-reroll"
                data-action="rerollMiltankFarmRequest"
                data-arg={snap.selectedPastureUid}
                disabled={!snap.canReroll}
                data-tooltip-variant="miltank-farm"
                {...(snap.rerollBlockedLabel ? miltankFarmTooltipHandlers(() => ({
                  title: '',
                  body: snap.rerollBlockedLabel ?? '',
                })) : {})}
              >
                {ui.rerollBtn}
                <span class="miltank-farm-reroll-cost">
                  ({snap.rerollCost ?? 5000}
                  <img src="img/pokedollars.png" class="resource-inline-icon miltank-farm-pd-icon" alt="">)
                </span>
              </button>
            </div>
          </div>
        {:else}
          <p class="miltank-farm-request-empty">{ui.noRequest}</p>
        {/if}
      </div>

      <!-- Menaces en approche -->
      {#if snap.hasApproachingThreat}
        <div class="miltank-farm-section miltank-farm-threat-approach">
          <h3 class="miltank-farm-section-title">{snap.threatApproachBannerLabel ?? ui.threatApproachBanner}</h3>
          <p class="miltank-farm-threat-hint">{ui.threatEngageHint}</p>
          <div class="miltank-farm-threat-engage-list">
            {#each snap.activeThreatSprites as threat (threat.id)}
              <button
                type="button"
                class="miltank-farm-btn miltank-farm-btn--threat"
                data-action="requestFarmThreatEngage"
                data-arg={threat.id}
              >
                {#if hasGuardianOverworldSprites(threat.displaySpecies)}
                  <span
                    class="miltank-farm-threat-engage-sprite threat-engage-face-{threat.approachFacing}"
                    style={guardianOverworldStyleString(threat.displaySpecies, false)}
                    aria-hidden="true"
                  ></span>
                {:else if threat.spriteUrl}
                  <img
                    class="miltank-farm-threat-engage-fallback"
                    src={threat.spriteUrl}
                    alt=""
                    width="24"
                    height="24"
                  />
                {/if}
                <span>{threat.label}</span>
              </button>
            {/each}
          </div>
        </div>
      {/if}

      <!-- Protection & Soins -->
      {#if snap.guardiansUnlocked && snap.selectedPastureSprite}
        <div class="miltank-farm-section miltank-farm-guardians">
          <h3 class="miltank-farm-section-title">{ui.guardianTitle}</h3>
          {#if snap.selectedPastureSprite.recentRepelled && snap.selectedPastureSprite.repelledLabel}
            <p class="miltank-farm-repelled-modal">{snap.selectedPastureSprite.repelledLabel}</p>
          {/if}
          <div class="miltank-farm-guardian-layout">
            <div class="miltank-farm-guardian-main">
              <MiltankGuardianPicker
                pastureUid={snap.selectedPastureSprite.uid}
                pastureName={snap.selectedPastureSprite.name}
                candidates={snap.selectedGuardianCandidates}
                hasGuardian={snap.selectedPastureSprite.hasGuardian}
                guardianName={snap.selectedPastureSprite.guardianName}
                guardianSpriteUrl={snap.selectedPastureSprite.guardianSpriteUrl}
                ui={ui}
                placement="bottom"
              />
            </div>
            <aside class="miltank-farm-pasture-heal" aria-label={ui.pastureHealTitle}>
              {#if snap.selectedPastureSprite.debuffActive}
                <div class="miltank-farm-injury-card">
                  <div class="miltank-farm-injury-head">
                    <div class="miltank-farm-injury-title-group">
                      <span class="miltank-farm-injury-badge">⚠ Blessée par un prédateur</span>
                      <span class="miltank-farm-injury-timer">Reste : <strong>{snap.selectedPastureSprite.debuffLabel?.replace(/^Blessée\s*\(/i, '').replace(/\)$/, '') ?? ''}</strong></span>
                    </div>
                    <span class="miltank-farm-injury-malus">Production −50 %</span>
                  </div>
                  <div class="miltank-farm-pasture-heal-row">
                    {#each snap.pastureHealOptions as opt (opt.itemKey)}
                      <button
                        type="button"
                        class="miltank-farm-pasture-heal-btn miltank-farm-btn miltank-farm-btn--chip"
                        data-action="healPastureDebuff"
                        data-arg={opt.itemKey}
                        disabled={!opt.canUse}
                        data-tooltip-variant="miltank-farm"
                        {...(opt.blockedLabel && !opt.canUse
                          ? miltankFarmTooltipHandlers(() => ({ title: '', body: opt.blockedLabel ?? '' }))
                          : {})}
                      >
                        {#if opt.itemIconUrl}
                          <img
                            class="miltank-farm-pasture-heal-icon item-sprite-img"
                            src={opt.itemIconUrl}
                            alt=""
                            width="20"
                            height="20"
                            loading="lazy"
                            decoding="async"
                          />
                        {/if}
                        <span class="miltank-farm-pasture-heal-text">
                          <span class="miltank-farm-pasture-heal-name">{opt.itemName}</span>
                          <span class="miltank-farm-pasture-heal-meta">
                            <span class="miltank-farm-pasture-heal-reduction">{opt.effectPreviewLabel ?? opt.reductionLabel}</span>
                            <span class="miltank-farm-pasture-heal-owned">×{opt.owned}</span>
                          </span>
                        </span>
                      </button>
                    {/each}
                  </div>
                </div>
              {:else}
                <div class="miltank-farm-heal-healthy">
                  <span class="miltank-farm-heal-healthy-icon">✨</span>
                  <span class="miltank-farm-heal-healthy-text">En pleine forme (aucune blessure active)</span>
                </div>
              {/if}
            </aside>
          </div>
        </div>
      {/if}

      <!-- Talents (Grille avec jauge segmentée 10 crans et coût explicite) -->
      <div class="miltank-farm-talents miltank-farm-section">
        <div class="miltank-farm-section-header">
          <h3 class="miltank-farm-section-title">{ui.talentTitle}</h3>
          {#if snap.talentPointsAvailable > 0}
            <span class="miltank-farm-talent-points">{ui.talentPointsLabel}: {snap.talentPointsAvailable}</span>
          {/if}
        </div>
        <div class="miltank-farm-talent-grid">
          {#each snap.talentBranches as branch (branch.key)}
            <div class="miltank-farm-talent-card">
              <div class="miltank-farm-talent-head">
                <strong class="miltank-farm-stat-value">{branch.label}</strong>
                <span class="miltank-farm-talent-rank">Nv. {branch.rank}/{branch.maxRank}</span>
              </div>
              {#if branch.description}
                <span class="miltank-farm-talent-desc">{branch.description}</span>
              {/if}
              <p class="miltank-farm-talent-bonus">
                {branch.bonusText}
                {#if branch.nextBonusText}
                  {' → '}<span class="miltank-farm-next-val">{branch.nextBonusText}</span>
                {/if}
              </p>
              <!-- Jauge segmentée 10 crans -->
              <div class="miltank-farm-talent-pips" role="progressbar" aria-valuenow={branch.rank} aria-valuemin="0" aria-valuemax={branch.maxRank}>
                {#each Array(branch.maxRank) as _, i}
                  <span class="miltank-farm-pip" class:miltank-farm-pip--filled={i < branch.rank}></span>
                {/each}
              </div>
              <button
                type="button"
                class="mastery-invest-btn miltank-farm-talent-btn"
                class:mastery-invest-active={branch.canInvest}
                class:mastery-invest-maxed={branch.rank >= branch.maxRank}
                data-action="investMiltankFarmTalent"
                data-arg={branch.key}
                disabled={!branch.canInvest}
              >
                {#if branch.rank >= branch.maxRank}
                  MAX
                {:else if branch.canInvest}
                  {ui.talentInvestBtn} (1 pt)
                {:else}
                  {ui.talentInvestBtn} (1 pt requis)
                {/if}
              </button>
            </div>
          {/each}
        </div>
      </div>

      <!-- Pied de page : récolte rapide seulement si non plein (pas de doublon avec l'alerte haute) -->
      {#if !stockFull && snap.storedMilk > 0}
        <div class="miltank-farm-footer-actions">
          <button
            type="button"
            class="miltank-farm-btn miltank-farm-btn--secondary miltank-farm-btn--claim miltank-farm-btn--footer-claim"
            data-action="claimPastureMilk"
            data-arg={snap.selectedPastureUid}
            disabled={!snap.canClaimSelected}
          >
            <img src={MILK_ICON_URL} alt="" class="miltank-farm-btn-icon" width="14" height="14" />
            {ui.claimBtn} ({snap.storedMilk})
          </button>
        </div>
      {/if}
    </div>
  {/if}
</div>

{#if snap.pendingThreatEngageId}
  <MiltankGuardianPicker
    mode="combat"
    threatId={snap.pendingThreatEngageId}
    pastureUid={snap.activeThreatSprites.find((t) => t.id === snap.pendingThreatEngageId)?.pastureUid ?? snap.selectedPastureUid}
    pastureName={engagePastureName}
    candidates={snap.threatCombatCandidates}
    hasGuardian={false}
    guardianName={null}
    guardianSpriteUrl={null}
    ui={snap.ui}
    open={true}
    onClose={() => game?.cancelFarmThreatEngage()}
  />
{/if}
